item.aggregated_output:
  1	# Deploy Cross-Account Role for PHD access
  2	
  3	# Parameters
  4	provider "aws" {
  5	    region  = var.aha_primary_region
  6	    default_tags {
  7	      tags = "${var.default_tags}"
  8	    }
  9	}
 10	
 11	variable "aha_primary_region" {
 12	    description = "Primary region where AHA solution will be deployed"
 13	    type        = string
 14	    default     = "us-east-1"
 15	}
 16	
 17	variable "default_tags" {
 18	    description = "Tags used for the AWS resources created by this template"
 19	    type        = map
 20	    default     = {
 21	      Application      = "AHA-Solution"
 22	    }
 23	}
 24	
 25	variable "OrgMemberAccountId" {
 26	  type = string 
 27	  description = "AWS Account ID of the AWS Organizations Member Account that will run AWS Health Aware"
 28	
 29	  validation {
 30	    condition     = length(var.OrgMemberAccountId) == 12
 31	    error_message = "The OrgMemberAccountId must be a valid AWS Account ID."
 32	  }
 33	}
 34	
 35	# Random id generator
 36	resource "random_string" "resource_code" {
 37	  length  = 8
 38	  special = false
 39	  upper   = false
 40	}
 41	
 42	# aws_iam_role.AWSHealthAwareRoleForPHDEvents:
 43	resource "aws_iam_role" "AWSHealthAwareRoleForPHDEvents" {
 44	    assume_role_policy    = jsonencode(
 45	        {
 46	            Statement = [
 47	                {
 48	                    Action    = "sts:AssumeRole"
 49	                    Effect    = "Allow"
 50	                    Principal = {
 51	                        AWS = "arn:aws:iam::${var.OrgMemberAccountId}:root"
 52	                    }
 53	                },
 54	            ]
 55	            Version   = "2012-10-17"
 56	        }
 57	    )
 58	    name                  = "AWSHealthAwareRoleForPHDEvents-${random_string.resource_code.result}"
 59	    description           = "Grants access to PHD event"
 60	    path                  = "/"
 61	
 62	    inline_policy {
 63	        name   = "AllowHealthCalls"
 64	        policy = jsonencode(
 65	            {
 66	                Statement = [
 67	                    {
 68	                        Action   = [
 69	                            "health:DescribeAffectedAccountsForOrganization",
 70	                            "health:DescribeAffectedEntitiesForOrganization",
 71	                            "health:DescribeEventDetailsForOrganization",
 72	                            "health:DescribeEventsForOrganization",
 73	                            "health:DescribeEventDetails",
 74	                            "health:DescribeEvents",
 75	                            "health:DescribeEventTypes",
 76	                            "health:DescribeAffectedEntities",
 77	                        ]
 78	                        Effect   = "Allow"
 79	                        Resource = "*"
 80	                    },
 81	                ]
 82	            }
 83	        )
 84	    }
 85	    inline_policy {
 86	        name   = "AllowsDescribeOrg"
 87	        policy = jsonencode(
 88	            {
 89	                Statement = [
 90	                    {
 91	                        Action   = [
 92	                            "organizations:ListAccounts",
 93	                            "organizations:ListAWSServiceAccessForOrganization",
 94	                            "organizations:DescribeAccount",
 95	                        ]
 96	                        Effect   = "Allow"
 97	                        Resource = "*"
 98	                    },
 99	                ]
100	            }
101	        )
102	    }
103	}
104	
105	
106	output "AWSHealthAwareRoleForPHDEventsArn" {
107	  value       = aws_iam_role.AWSHealthAwareRoleForPHDEvents.arn
108	}
109
